WITH RankedPosts AS (SELECT p.Id AS PostId, p.Title, p.CreationDate, p.Score, ROW_NUMBER() OVER (PARTITION BY p.OwnerUserId ORDER BY p.CreationDate DESC NULLS FIRST) AS PostRank FROM Posts AS p WHERE p.PostTypeId = 1 AND p.CreationDate >= CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '1' YEAR), UserStats AS (SELECT u.Id AS UserId, u.DisplayName, COUNT(DISTINCT p.Id) AS QuestionCount, COUNT(DISTINCT c.Id) AS CommentCount, SUM(v.BountyAmount) AS TotalBounty FROM Users AS u LEFT JOIN Posts AS p ON u.Id = p.OwnerUserId LEFT JOIN Comments AS c ON p.Id = c.PostId LEFT JOIN Votes AS v ON u.Id = v.UserId GROUP BY u.Id, u.DisplayName), PostCloseReasons AS (SELECT ph.PostId, GROUP_CONCAT(crt.Name, ', ') AS CloseReasons FROM PostHistory AS ph JOIN CloseReasonTypes AS crt ON CAST(ph.Comment AS Nullable(Int32)) = crt.Id WHERE ph.PostHistoryTypeId = 10 GROUP BY ph.PostId) SELECT us.DisplayName, us.QuestionCount, us.CommentCount, us.TotalBounty, rp.Title, rp.CreationDate, rp.Score, PCR.CloseReasons FROM UserStats AS us INNER JOIN RankedPosts AS rp ON us.UserId = rp.PostId LEFT JOIN PostCloseReasons AS PCR ON rp.PostId = PCR.PostId WHERE us.QuestionCount > 5 AND (NOT (us.TotalBounty IS NULL) OR us.CommentCount > 10) AND rp.PostRank = 1 ORDER BY us.TotalBounty DESC NULLS FIRST, rp.CreationDate DESC NULLS FIRST LIMIT 100